// Read the CRM export. In production this node is a webhook or a
// scheduled pull from the CRM's API — same shape, same downstream nodes.
const fs = require('fs');
const path = require('path');
const base = $env.EP01_DIR;
const raw = fs.readFileSync(path.join(base, 'data', 'crm-export.csv'), 'utf8');
const [header, ...lines] = raw.trim().split('\n');
const cols = header.split(',');
return lines.map((line) => {
  const vals = line.split(',');
  const row = Object.fromEntries(cols.map((c, i) => [c, vals[i]]));
  return { json: row };
});

// Keep only closed-won deals and price the invoice.
// Quarterly deals bill a third per month; one-time bills in full.
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  if (d.status !== 'won') continue;
  const amount = Number(d.amount_usd);
  const billed =
    d.billing_cycle === 'quarterly' ? Math.round((amount / 3) * 100) / 100 :
    amount;
  out.push({
    json: {
      invoice_id: 'INV-' + d.deal_id.replace('D-', '') + '-' + d.close_date.replaceAll('-', '').slice(0, 6),
      client: d.client,
      email: d.email,
      billed_usd: billed,
      cycle: d.billing_cycle,
      close_date: d.close_date,
    },
  });
}
return out;

// Emit one invoice HTML per deal, plus a chase list and a run summary.
// HTML instead of a PDF service: every browser prints HTML to PDF, and it
// removes the paid dependency this workflow exists to replace.
const fs = require('fs');
const path = require('path');
const base = $env.EP01_DIR;
const outDir = path.join(base, 'out');
fs.mkdirSync(path.join(outDir, 'invoices'), { recursive: true });

const items = $input.all();
const today = '2026-08-05';
let total = 0;

for (const { json: inv } of items) {
  total += inv.billed_usd;
  const html = `<!doctype html><html><head><meta charset="utf-8"><title>${inv.invoice_id}</title>
<style>body{font:15px/1.5 -apple-system,sans-serif;max-width:640px;margin:48px auto;color:#111}
h1{font-size:22px}table{width:100%;border-collapse:collapse;margin-top:24px}
td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}
.total{font-weight:700;font-size:18px}.muted{color:#666}</style></head><body>
<h1>Invoice ${inv.invoice_id}</h1>
<p class="muted">Issued ${today} · due in 14 days</p>
<p><strong>${inv.client}</strong><br>${inv.email}</p>
<table><tr><th>Description</th><th>Amount</th></tr>
<tr><td>Services — ${inv.cycle} billing (closed ${inv.close_date})</td><td>$${inv.billed_usd.toLocaleString('en-US')}</td></tr>
<tr><td class="total">Total due</td><td class="total">$${inv.billed_usd.toLocaleString('en-US')}</td></tr></table>
</body></html>`;
  fs.writeFileSync(path.join(outDir, 'invoices', inv.invoice_id + '.html'), html);
}

const chase = items.map(({ json: i }) => ({
  invoice_id: i.invoice_id, client: i.client, email: i.email,
  amount: i.billed_usd, chase_after: '2026-08-19',
}));
fs.writeFileSync(path.join(outDir, 'chase-list.json'), JSON.stringify(chase, null, 2));

const summary = {
  run_date: today,
  invoices_created: items.length,
  total_billed_usd: Math.round(total * 100) / 100,
};
fs.writeFileSync(path.join(outDir, 'summary.json'), JSON.stringify(summary, null, 2));
return [{ json: summary }];
